"""Verify editable authoring paths, fixed-baseline pixels and precise change scope."""
import json
from pathlib import Path
import subprocess
import sys
import tempfile
import unittest
import PIL

ROOT=Path(__file__).resolve().parents[1]
sys.path.insert(0,str(ROOT/'recipes'))
from pixelart import render,verify_edit,PixelArtError
from pixelart.metadata import rgba_digest
import icons,buttons,courier128,scene256

# Frozen from the unchanged rc.2 ZIP before adding recipes, not regenerated by checks.
BASELINE={
    'icons':'bca4b33183e3ebe9ca0cf194b2056c694009a6960f52dd6c4cd72244b8b4b842',
    'buttons':'5283e8390cd70474ad16020c359c1e7dbfee21e1a0fed30b1a960dd813266029',
    'courier128':'29a3152422867a08d487aa5cadbf58f1b4abcfe937919bd9d606db2305b3f1a2',
    'scene256':'a1f2632ff68c1c88bc05a0d4e4878c321f1d1c296dabda296769d90f87dcdc13',
}


class RecipeTests(unittest.TestCase):
    def test_default_pixels_match_frozen_candidate_at_fixed_pillow_baseline(self):
        images=dict(icons=render(icons.make_specs()[0]),buttons=render(buttons.make_spec()),
            courier128=render(courier128.make_spec()),scene256=scene256.make_files()['asset.png'])
        for name,image in images.items():
            with self.subTest(recipe=name):
                # Mask polygon rasterization is explicitly dependency-sensitive.
                if PIL.__version__=='12.3.0' or name in ('icons','buttons'):
                    self.assertEqual(rgba_digest(image),BASELINE[name])
        self.assertEqual([c['name'] for c in images['buttons'].info['pixelart']['cells']],list(buttons.STATES))

    def test_icon_palette_role_changes_no_geometry_or_atlas_layout(self):
        original=render(icons.make_specs()[0]);edited=render(icons.make_specs('F5C26B')[0])
        self.assertEqual(original.getchannel('A').tobytes(),edited.getchannel('A').tobytes())
        self.assertEqual(original.info['pixelart'],edited.info['pixelart'])
        before=original.tobytes();after=edited.tobytes();changed=0
        for i in range(0,len(before),4):
            if before[i:i+4]!=after[i:i+4]:
                self.assertEqual(before[i:i+4],bytes.fromhex('D8E3EDFF'))
                self.assertEqual(after[i:i+4],bytes.fromhex('F5C26BFF'));changed+=1
        self.assertGreater(changed,0)

    def test_ui_width_content_and_one_state_preserve_state_contract(self):
        before=render(buttons.make_spec());after=render(buttons.make_spec(hover='426B83'))
        difference=verify_edit(after,before,regions=[[32,0,32,18]])
        self.assertTrue(difference['valid']);self.assertGreater(difference['changed_inside'],0)
        files=buttons.make_files(width=64,hover='426B83',content=[28,4,30,10])
        self.assertEqual(files['asset.png'].size,(192,36))
        cells=files['layout.json']['atlas']['cells'];regions=files['context.json']['regions']
        self.assertEqual([c['name'] for c in cells],list(buttons.STATES))
        for cell,region in zip(cells,regions):
            x,y,w,h=region['rect'];self.assertEqual([x-cell['x'],y-cell['y'],w,h],[28,4,30,10])
            patch=files['asset.png'].crop((x,y,x+w,y+h))
            self.assertEqual(len(patch.getcolors()),1,'Text reservation must not cover the glyph or state marks')
        with self.assertRaises(PixelArtError):buttons.make_files(width=24,content=[23,4,10,10])

    def test_courier_stripe_edit_keeps_silhouette_and_unrelated_pixels(self):
        before=render(courier128.make_spec());after=render(courier128.make_spec(stripe='E17B57',stripe_light='F9D5A0'))
        difference=verify_edit(after,before,regions=[[42,68,48,10]])
        self.assertTrue(difference['valid']);self.assertGreater(difference['changed_inside'],0)
        self.assertEqual(before.getchannel('A').tobytes(),after.getchannel('A').tobytes())

    def test_scene_rebuild_uses_new_components_and_matches_self_contained_control(self):
        before=scene256.make_files();after=scene256.make_files(roof='684C6A',roof_light='A07A89')
        for name in ('terrain','bridge','details'):
            self.assertEqual(before[f'scene/{name}.png'].tobytes(),after[f'scene/{name}.png'].tobytes())
        self.assertNotEqual(before['scene/mill.png'].tobytes(),after['scene/mill.png'].tobytes())
        self.assertEqual(after['asset.png'].tobytes(),render(after['asset.json']).tobytes())
        from pixelart import assemble
        sources={p['image']:after[p['image']] for p in after['project.json']['parts']}
        self.assertEqual(assemble(after['project.json'],sources)[0].tobytes(),after['asset.png'].tobytes())

    def test_recipe_cli_from_unrelated_cwd_rejects_partial_overwrite_and_bad_content(self):
        with tempfile.TemporaryDirectory(prefix='配方 task space ') as directory:
            root=Path(directory)
            def run(recipe,*args,expected=0):
                result=subprocess.run([sys.executable,'-B',str(ROOT/f'recipes/{recipe}.py'),*map(str,args)],
                    cwd=root,capture_output=True,text=True,encoding='utf-8',timeout=30)
                self.assertEqual(result.returncode,expected,result.stderr);return result
            run('icons','--out-dir',root/'icons')
            previous=(root/'icons/asset.png').read_bytes();(root/'icons/layout.json').unlink()
            run('icons','--out-dir',root/'icons','--ink','F5C26B',expected=2)
            self.assertEqual(previous,(root/'icons/asset.png').read_bytes())
            self.assertFalse((root/'icons/layout.json').exists())
            run('buttons','--out-dir',root/'bad','--width','24','--content','23','4','10','10',expected=2)
            self.assertFalse((root/'bad').exists())
